const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('path');

// Generated by `npm run update-intros` (runs on postinstall).
// src/contants/paths.js builds the `/intro/<slug>` routes from this file.
const intros = require(path.join(__dirname, '..', 'src', 'contants', 'intros.json'));

test('intros.json is a non-empty list of intro definitions', () => {
  assert.ok(Array.isArray(intros), 'intros.json must contain an array');
  assert.ok(intros.length > 0, 'intros.json must not be empty');
});

test('every intro has the fields used to build routes and pages', () => {
  intros.forEach((intro) => {
    assert.equal(typeof intro.slug, 'string', 'slug must be a string');
    assert.ok(intro.slug.length > 0, 'slug must not be empty');
    assert.equal(typeof intro.title, 'string', `'${intro.slug}' must have a title`);
  });
});

test('intro slugs are unique (each one becomes a distinct /intro/<slug> route)', () => {
  const slugs = intros.map((intro) => intro.slug);
  assert.equal(new Set(slugs).size, slugs.length, 'duplicate slugs found');
});
